import{z as n,x as m,o as i,c as p,q as s,j as l,D as a,d as t,s as o,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"hrtimer","description":"","frontmatter":{"title":"hrtimer","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hrtimer.md","filePath":"cs/hrtimer.md","lastUpdated":1791063341000}'),d={name:"cs/hrtimer.md"};function h(A,e,c,f,C,u){const E=m("Mermaid");return i(),p("div",null,[e[2]||(e[2]=s('<h1 id="hrtimer" tabindex="-1">hrtimer <a class="header-anchor" href="#hrtimer" aria-label="Permalink to &quot;hrtimer&quot;">​</a></h1><div class="epigraph"><p>高精度定时器按绝对或相对纳秒期限排队；到期时靠时钟事件设备中断，而不是等下一个 HZ 滴答。</p><footer>—— 据 Gleixner 对 Linux hrtimer 的设计；POSIX clock_nanosleep 整理</footer></div><p><a href="/cs/jiffies">上一课</a>的粒度是毫秒级。<a href="/cs/realtime-sched">实时调度</a> 需要更紧的唤醒。<a href="/cs/io-uring">io_uring</a> 与 epoll 的超时若只对齐滴答，尾延迟差。缺口是 <strong>hrtimer</strong>：独立于 timer wheel 的期限队列，加上可编程的下一中断时刻。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提高 HZ 会增加中断负荷，仍是均匀滴答。无滴答内核在空闲时甚至关掉周期性 IRQ。缺口：把下一个最近期限编程进时钟事件设备；到期只跑那个回调；没有期限时可以睡到下一事件。软件侧用红黑树（或时间线）按到期排序。用户 <code>clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, …)</code> 走这条。</p><p><span class="marginnote">直觉类比：jiffies 滴答像定班公交——不管有没有人上车，固定间隔发一班，到站时刻只能对齐班次；hrtimer 像专车——你说几点走，车几点到门口。班次加密（提高 HZ）能让公交近似专车，但空驶的中断成本全城买单。</span></p><p>本课不把 clocksource 与 clockevent 的驱动列表背完。</p><p><span class="marginnote">slack 允许内核把期限稍微合并以省中断。实时任务可以要最小 slack。与 jiffies 定时器并存：粗的仍走 wheel，细的走 hrtimer。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注册 hrtimer：给定 ktime 与回调。内核计算最早期限，编程设备。IRQ：执行到期回调（可唤醒进程、推进网络重传等），再编程下一期限。回调不可长时间占 CPU，重活丢工作队列——对接已有下半部课。不要用 hrtimer 在回调里做阻塞 I/O。</p><p><span class="marginnote">常见误区：在回调里做阻塞 I/O 或重活。回调跑在中断上下文里，此时没有进程背景可睡——一旦阻塞，这条 CPU 上的其他中断与调度全被拖着走。正确做法是回调只做唤醒或标记，重活丢给工作队列去进程上下文里慢慢干。</span></p>',11)),(i(),l(B,null,{default:a(()=>[o(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DL%5B%22%E4%B8%8B%E4%B8%80%E6%9C%80%E6%97%A9%E6%9C%9F%E9%99%90%22%5D%20--%3E%20PROG%5B%22%E7%BC%96%E7%A8%8B%E6%97%B6%E9%92%9F%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20PROG%20--%3E%20IRQ%5B%22%E5%88%B0%E6%9C%9F%E4%B8%AD%E6%96%AD%22%5D%0A%20%20IRQ%20--%3E%20CB%5B%22%E5%9B%9E%E8%B0%83%22%5D%0A%20%20CB%20--%3E%20PROG%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,"hrtimer 把时间从「节拍计数」升级为「事件驱动的期限」。调度器的高精度抢占、TCP 细超时、用户 nanosleep 共用。它不取代 jiffies 记账；CFS 仍可按纳秒差更新 vruntime，来源可以是同一 clocksource。与组成课的锁存器无关。",-1)),e[5]||(e[5]=r("p",null,"一个定时请求进来，走时间轮还是走 hrtimer？按粒度分工看：",-1)),(i(),l(B,null,{default:a(()=>[o(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%AE%9A%E6%97%B6%E9%9C%80%E6%B1%82%E5%88%B0%E6%9D%A5%22%5D%20--%3E%20Q%7B%22%E6%9C%9F%E9%99%90%E7%B2%92%E5%BA%A6%E8%A6%81%E6%B1%82%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%B2%97%EF%BC%9A%E5%87%A0%E5%8D%81%20ms%20%E7%BA%A7%E5%8D%B3%E5%8F%AF%22%7C%20WHEEL%5B%22jiffies%20%E6%97%B6%E9%97%B4%E8%BD%AE%EF%BC%9A%E8%AE%B0%E4%B8%8B%E5%9C%88%E6%95%B0%22%5D%0A%20%20Q%20--%3E%7C%22%E7%BB%86%EF%BC%9A%E5%BE%AE%E7%A7%92%E7%BA%A7%E6%9C%9F%E9%99%90%22%7C%20HR%5B%22hrtimer%EF%BC%9A%E6%8C%89%E6%9C%9F%E9%99%90%E7%BC%96%E7%A8%8B%E6%97%B6%E9%92%9F%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20WHEEL%20--%3E%20TICK%5B%22%E4%B8%8B%E4%B8%80%E4%B8%AA%20HZ%20%E6%BB%B4%E7%AD%94%E7%BB%9F%E4%B8%80%E5%A4%84%E7%90%86%22%5D%0A%20%20HR%20--%3E%20EV%5B%22%E5%88%B0%E6%9C%9F%E5%8D%B3%E4%B8%AD%E6%96%AD%EF%BC%8C%E4%B8%8D%E7%AD%89%E6%BB%B4%E7%AD%94%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<p><span class="marginnote">数字实例：HZ=250 时一个 jiffies 滴答是 4 ms——用时间轮定 10 ms 的超时，实际可能落在 8 ms 到 12 ms 之间的任意滴答上。hrtimer 直接把 10 ms 这个绝对时刻编程进时钟事件设备，误差从「半个滴答」缩到微秒级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证在虚拟机里能得到主机级精度。不引入 timerfd 的全部接口，只承认期限可变成 fd 上的可读。下一课：字符设备上的人机接口——终端与伪终端，shell 与 SSH 都靠它。</p><p>后课默认：内核可按纳秒期限唤醒。字节流的终端行规程与 PTY，下一课 tty。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>hrtimer 按期限编程时钟事件，不绑死 HZ。</li><li>与 jiffies wheel 并存，服务 nanosleep 与实时唤醒。</li><li>终端作为进程的控制设备，是 tty 课的缺口。</li><li>出处：Gleixner, Linux hrtimer；POSIX clocks；Love, <em>LKD</em>。</li></ul>',6))])}const T=n(d,[["render",h]]);export{_ as __pageData,T as default};
